import unittest

def flatten(suite):
    for item in suite:
        if isinstance(item, unittest.TestSuite):
            yield from flatten(item)
        else:
            yield item

loaded = unittest.defaultTestLoader.discover('tests')
selected = unittest.TestSuite(
    test for test in flatten(loaded)
    if '.test_matlab_' not in test.id()
    and '.P15RetainedEvidenceTests.' not in test.id()
    and not test.id().endswith(
        'P15IdentityAndArtifactTests.test_complete_artifact_set_has_clean_terminal_newlines_and_bounds'
    )
)
result = unittest.TextTestRunner(verbosity=1).run(selected)
print(
    f'P15 INTENDED SOURCE-WIDE: run={result.testsRun} '
    f'failures={len(result.failures)} errors={len(result.errors)} skips={len(result.skipped)}'
)
raise SystemExit(not result.wasSuccessful())
